  "dialogue": {
    "IRIS_COMMANDER": {
      "name": "Vale",
      "role": "Keeper of the valley",
      "text": "Osei needs iron for the mill tools. The western rail line leads to a cutting yard that still thinks the war is on. Down below, our history is drowning. Pick a problem and leave this place better than you found it.",
      "action": "Field journal",
      "intent": "mission-console",
      "variants": [
        {
          "quest": "homecoming",
          "state": "complete",
          "text": "Listen. The cutting yard has gone quiet. People can cross the millrace again. Even the archive smells like paper instead of pond water. Welcome home."
        },
        {
          "quest": "last-shift",
          "state": "complete",
          "text": "No more night shift. Good. There is a recording waiting on the mountain, and I would rather you reached it in one piece."
        }
      ]
    },
    "IRIS_ENGINEER": {
      "name": "Osei",
      "role": "Maker & mender",
      "text": "Bring me 24 iron ore. There is a vein by Willow Mill, east of here. I’ll cut enough timber for the crossing. Keep the water flowing underneath; we still need the mill.",
      "action": "Restore the lodge",
      "intent": "repair-base",
      "variants": [
        {
          "quest": "mill-bridge",
          "state": "complete",
          "text": "A bridge you can actually walk across. I could get used to that. If the lodge gets battered, I can still put it back together."
        },
        {
          "quest": "mill-supplies",
          "state": "complete",
          "text": "The timber is yours. Lay a level deck between the mill’s wooden abutments, following the faded planks. Connect it to the bank so it holds."
        }
      ]
    },
    "SURVEYOR": {
      "name": "The archivist",
      "role": "A very patient reader",
      "text": "Water follows the openings you give it. There is a hollow beneath the archive. That might be all you need.",
      "variants": [
        {
          "quest": "drowned-archive",
          "state": "complete",
          "text": "The pages are drying. The oldest map calls the mountain a listening post, not an observatory. I wonder who is on the other end."
        }
      ]
    }
  },
  "signs": [
    {
      "anchor": "hearth.vale",
      "offset": [30,-51],
      "text": "HEARTHWOOD LODGE"
    },
    {
      "anchor": "hearth.osei",
      "offset": [11,-36],
      "text": "THE WORKSHOP"
    },
    {
      "anchor": "mill.bridge",
      "offset": [0,-33],
      "text": "WILLOW MILL"
    }
  ],
  "residents": [
    {
      "id": 1,
      "species": "IRIS_COMMANDER",
      "anchor": "hearth.vale",
      "roamRadius": 8,
      "dialogue": {
        "name": "Vale",
        "role": "Keeper of Hearthwood",
        "text": "The bell on Windward has fallen silent. Now the roots wake hungry, and the river forgets its banks. Help Osei mend our crossing. Then follow the old paths: the wood, the water, the fire, and finally the bell.",
        "action": "Journal",
        "intent": "mission-console"
      }
    },
    {
      "id": 2,
      "species": "IRIS_ENGINEER",
      "anchor": "hearth.osei",
      "roamRadius": 8,
      "dialogue": {
        "name": "Osei",
        "role": "Maker and mender",
        "text": "We still have a mill, if we can reach it. Bring me iron from the exposed vein beside Willow Mill. I will cut fresh bridge timber. A good bridge leaves the water room to breathe.",
        "action": "Use the workbench",
        "intent": "workshop"
      }
    },
    {
      "id": 3,
      "species": "SURVEYOR",
      "anchor": "hearth.mira",
      "roamRadius": 8,
      "dialogue": {
        "name": "Mira",
        "role": "Keeper of the lost pages",
        "text": "The archive is drowning below us. There is an empty cavern beneath the reading hall. Give the water a way out, and the old words may yet survive.",
        "action": "Journal",
        "intent": "mission-console"
      }
    },
    {
      "id": 4,
      "species": "IRIS_ENGINEER",
      "anchor": "foundry.brann",
      "roamRadius": 8,
      "dialogue": {
        "name": "Brann",
        "role": "Smith of the Cinder Court",
        "text": "The Castellan has claimed my forge. Watch the glow beneath its hammer: that is where the blow will fall. Break its oath of cinders and I can make the bell a heart again.",
        "action": "Use the forge",
        "intent": "workshop"
      }
    },
    {
      "id": 5,
      "species": "IRIS_COMMANDER",
      "anchor": "watchwood.rowan",
      "roamRadius": 8,
      "dialogue": {
        "name": "Rowan",
        "role": "Warden of Watchwood",
        "text": "The hart once guarded every seedling here. Something thorny has grown around its heart. Its antlers warn before it charges. Let it pass, then strike the roots at its flank.",
        "action": "Journal",
        "intent": "mission-console"
      }
    },
    {
      "id": 6,
      "species": "SURVEYOR",
      "anchor": "archive.senna",
      "roamRadius": 8,
      "dialogue": {
        "name": "Senna",
        "role": "Herbalist of the low water",
        "text": "Do not mistake still water for a safe floor. The Matron listens from the silt. Cold will slow her, and a channel will take her water away.",
        "action": "Journal",
        "intent": "mission-console"
      }
    },
    {
      "id": 7,
      "species": "IRIS_ENGINEER",
      "anchor": "hearth.iven",
      "roamRadius": 8,
      "dialogue": {
        "name": "Iven",
        "role": "Trader of small wonders",
        "text": "Bring copper ore for runes: Prism Choir ricochets through tight rooms, Hollow Star gathers foes before collapsing, and Faultline tears a seam through stone. Try combining them. Old cellar coffers hold runes and armor.",
        "action": "Browse wares",
        "intent": "workshop"
      }
    },
    {
      "id": 8,
      "species": "SURVEYOR",
      "anchor": "observatory.elowen",
      "roamRadius": 8,
      "dialogue": {
        "name": "Elowen",
        "role": "Last bell singer",
        "text": "The bellkeeper has swallowed every note. Bring the wood’s breath, the water’s memory, and the forge’s heart. When the bellkeeper falls, we will sing the valley awake.",
        "action": "Journal",
        "intent": "mission-console"
      }
    }
  ],
